// Split the comma-separated list into one item per hashtag,
// carrying the shared config fields onto each item so downstream nodes don't need to look them up again.
const config = $input.first().json;
const rawList = config.hashtags || '';

const items = rawList
  .split(',')
  .map(k => k.trim())
  .filter(k => k.length > 0)
  .map(keyword => ({
    json: {
      keyword,
      telegramChatId: config.telegramChatId
    }
  }));

if (items.length === 0) {
  throw new Error('No hashtags configured. Set at least one value in "Configure Your Search".');
}

return items;

