// Dedupe new posts across all searched keywords, using workflow static data.
// The Search Hashtag HTTP node replaces each item's JSON with the raw API
// response (count, results, ...), dropping the keyword/telegramChatId that
// Split Keywords attached. The HTTP node runs once per input item and keeps
// item order 1:1, so we recover those fields from Split Keywords by index.
const store = $getWorkflowStaticData('global');
if (!store.seenUrls) store.seenUrls = [];
if (typeof store.totalMentionsFound !== 'number') store.totalMentionsFound = 0;

const inputs = $input.all();
const configs = $('Split Hashtag Keywords').all();

const newItems = [];

for (let i = 0; i < inputs.length; i++) {
  const cfg = (configs[i] && configs[i].json) || {};
  const keyword = cfg.keyword;
  const telegramChatId = cfg.telegramChatId;
  const results = inputs[i].json.results || [];

  for (const post of results) {
    if (!post.url || store.seenUrls.includes(post.url)) continue;
    store.seenUrls.push(post.url);
    newItems.push({
      json: {
        ...post,
        matchedKeyword: keyword,
        telegramChatId
      }
    });
  }
}

store.totalMentionsFound += newItems.length;
store.lastRunAt = new Date().toISOString();

// Cap the stored list so it doesn't grow forever
if (store.seenUrls.length > 2000) {
  store.seenUrls = store.seenUrls.slice(-2000);
}

// On a manual test run with nothing new, send one confirmation message instead of staying silent
if (newItems.length === 0 && $execution.mode === 'manual') {
  const chatId = (configs[0] && configs[0].json.telegramChatId) || undefined;
  return [{
    json: {
      isSummary: true,
      telegramChatId: chatId,
      message: `✅ Test run complete. No new mentions found (checked ${configs.length} keyword(s)). Total mentions found all-time: ${store.totalMentionsFound}.`
    }
  }];
}

return newItems;
